#!/usr/bin/env node
/**
 * scripts/brand/ulara-kit.test.mjs — ULARA Ω 2-A: the kit's geometric gate.
 *
 * Plain `node --test` (no new dependencies). Verifies that the staged kit
 * (shared/brand/ulara/, generated by scripts/brand/ulara-kit.mjs from
 * shared/brand.json) is deterministic, structurally sound, and faithful to
 * the brand rules — so the future Gate-A rename stays a one-file change.
 *
 *   1. determinism      — the generator run twice into two temp dirs must
 *                         produce byte-identical file sets.
 *   2. structure        — every SVG is well-formed (comment-stripped tag
 *                         balance, <svg> root) with the expected viewBox /
 *                         width / height per seat.
 *   3. one cornerstone  — exactly ONE accent-coloured element per mark
 *                         (and exactly none in the mono version).
 *   4. one stroke       — every stroke-width in the mark family is a single
 *                         consistent value, and the stroke is ink.
 *   5. no retired arch  — the forbidden arc signature (assembled at
 *                         runtime — see the note at its test) in any
 *                         spacing; the mark family contains no arc
 *                         command at all.
 *   6. name round-trip  — brand.json parses; name_ar carries the damma
 *                         (the damma-less spelling appears nowhere in the
 *                         kit); name_en is the running-text form while the
 *                         all-caps lockup form appears ONLY in the -en
 *                         lockups' rendered content; the palette is pinned
 *                         to design-tokens.json color.brand.
 *   7. drift            — the committed kit byte-matches a fresh run
 *                         (regeneration is verification), and every file is
 *                         non-empty.
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, mkdtempSync } from "node:fs";
import { dirname, join } from "node:path";
import { tmpdir } from "node:os";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const KIT = join(ROOT, "scripts", "brand", "ulara-kit.mjs");
const BRAND_JSON = join(ROOT, "shared", "brand.json");
const TOKENS_JSON = join(ROOT, "shared", "design-tokens.json");
const COMMITTED = join(ROOT, "shared", "brand", "ulara");

/* ── the expected kit ────────────────────────────────────────────────── */
/* vb / w / h per seat; accents = occurrences of the accent hex in the
 * RENDERED content (comments stripped) — the single orange cornerstone. */
const FILES = {
  "mark.svg": { vb: "0 0 32 32", w: 32, h: 32, accents: 1 },
  "mark-mono.svg": { vb: "0 0 32 32", w: 32, h: 32, accents: 0 },
  "lockup-horizontal-ar.svg": { vb: "0 0 240 64", w: 240, h: 64, accents: 1 },
  "lockup-horizontal-en.svg": { vb: "0 0 240 64", w: 240, h: 64, accents: 1 },
  "lockup-vertical-ar.svg": { vb: "0 0 96 100", w: 96, h: 100, accents: 1 },
  "lockup-vertical-en.svg": { vb: "0 0 96 100", w: 96, h: 100, accents: 1 },
  "favicon-16.svg": { vb: "0 0 32 32", w: 16, h: 16, accents: 1 },
  "favicon-32.svg": { vb: "0 0 32 32", w: 32, h: 32, accents: 1 },
  "appicon-1024.svg": { vb: "0 0 1024 1024", w: 1024, h: 1024, accents: 1 },
  "og-1200x630.svg": { vb: "0 0 1200 630", w: 1200, h: 630, accents: 1 },
};
const NAMES = Object.keys(FILES).sort();

/* ── helpers ─────────────────────────────────────────────────────────── */
const stripComments = (xml) => xml.replace(/<!--[\s\S]*?-->/g, "");
const count = (hay, needle) => hay.split(needle).length - 1;

/** Comment-stripped XML tag balance (adequate for this generator's output:
 * attribute values never contain '>'). Asserts the <svg> root too. */
function assertWellFormed(name, raw) {
  const xml = stripComments(raw).trim();
  assert.ok(xml.startsWith("<svg "), `${name}: must start with an <svg> root`);
  assert.ok(xml.endsWith("</svg>"), `${name}: must end with </svg>`);
  const stack = [];
  for (const m of xml.matchAll(/<[^>]+>/g)) {
    const tag = m[0];
    if (tag.startsWith("<?") || tag.startsWith("<!")) continue;
    if (tag.startsWith("</")) {
      const close = tag.slice(2, -1);
      assert.equal(stack.pop(), close, `${name}: </${close}> closes the wrong element (stack: ${stack.join(",")})`);
    } else if (tag.endsWith("/>")) {
      /* self-closing — nothing to stack */
    } else {
      stack.push(tag.slice(1).split(/[\s>]/)[0]);
    }
  }
  assert.equal(stack.length, 0, `${name}: ${stack.length} unclosed element(s): ${stack.join(",")}`);
}

/* Run the generator into a fresh temp dir (subprocess = the real CLI). */
function runKit() {
  const dir = mkdtempSync(join(tmpdir(), "ulara-kit-"));
  execFileSync(process.execPath, [KIT, "--out", dir], { cwd: ROOT, encoding: "utf8" });
  return dir;
}

/* Two fresh runs, once for the whole file (determinism compares THEM;
 * every other assertion reads run A — the canonical regeneration). */
const RUN_A = runKit();
const RUN_B = runKit();
const read = (dir, name) => readFileSync(join(dir, name), "utf8");

/* ── 1. determinism ──────────────────────────────────────────────────── */
test("determinism: two runs of ulara-kit.mjs are byte-identical", () => {
  const a = readdirSync(RUN_A).sort();
  const b = readdirSync(RUN_B).sort();
  assert.deepEqual(a, NAMES, `run A must produce exactly the expected file set (got: ${a.join(", ")})`);
  assert.deepEqual(a, b, "run B must list the same files as run A");
  for (const name of NAMES) {
    assert.equal(
      Buffer.compare(readFileSync(join(RUN_A, name)), readFileSync(join(RUN_B, name))),
      0,
      `${name}: differs between two runs — the generator is not deterministic`,
    );
  }
});

/* ── 2. structure: parses, root, viewBox/dims ─────────────────────────── */
test("every SVG is well-formed with the expected viewBox and dimensions", () => {
  for (const name of NAMES) {
    const raw = read(RUN_A, name);
    const exp = FILES[name];
    assertWellFormed(name, raw);
    const root = stripComments(raw).match(/^<svg\b[^>]*>/)[0];
    assert.match(root, new RegExp(`viewBox="${exp.vb.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}"`), `${name}: viewBox must be ${exp.vb}`);
    assert.match(root, new RegExp(`\\bwidth="${exp.w}"`), `${name}: width must be ${exp.w}`);
    assert.match(root, new RegExp(`\\bheight="${exp.h}"`), `${name}: height must be ${exp.h}`);
  }
});

/* ── 3. exactly one accent element ───────────────────────────────────── */
test("the mark carries exactly ONE accent cornerstone (mono: none)", () => {
  const brand = JSON.parse(readFileSync(BRAND_JSON, "utf8"));
  const accent = brand.colors.accent;
  for (const name of NAMES) {
    const rendered = stripComments(read(RUN_A, name));
    const got = count(rendered, accent);
    assert.equal(got, FILES[name].accents, `${name}: expected ${FILES[name].accents} occurrence(s) of ${accent}, found ${got}`);
  }
  /* The cornerstone is a square rect, not a stroke — and only a rect. */
  for (const name of ["mark.svg", "mark-mono.svg", "favicon-16.svg", "favicon-32.svg"]) {
    const rects = [...stripComments(read(RUN_A, name)).matchAll(/<(rect)\b[^>]*\/>/g)].map((m) => m[0]);
    assert.equal(rects.length, 1, `${name}: the mark family is one stroke + one stone (found ${rects.length} rects)`);
  }
  const stone = stripComments(read(RUN_A, "mark.svg")).match(/<rect\b[^>]*\/>/)[0];
  assert.match(stone, new RegExp(`fill="${accent}"`), "mark.svg: the stone must be the accent rect");
});

/* ── 4. one stroke weight ────────────────────────────────────────────── */
test("stroke-weight consistency: one unified stroke in the mark family", () => {
  for (const name of ["mark.svg", "mark-mono.svg", "favicon-16.svg", "favicon-32.svg"]) {
    const widths = [...stripComments(read(RUN_A, name)).matchAll(/stroke-width="([^"]+)"/g)].map((m) => m[1]);
    assert.ok(widths.length >= 1, `${name}: at least one stroke-width`);
    assert.equal(new Set(widths).size, 1, `${name}: all stroke-widths must be equal (found ${widths.join(", ")})`);
    assert.ok([...stripComments(read(RUN_A, name)).matchAll(/stroke="([^"]+)"/g)].every((m) => m[1] === JSON.parse(readFileSync(BRAND_JSON, "utf8")).colors.ink), `${name}: the stroke must be brand ink`);
  }
});

/* ── 5. no retired arch geometry ─────────────────────────────────────── */
/* The gate pattern is ASSEMBLED from fragments, never spelled verbatim in
 * this file: scripts/brand/logo-gate.sh greps every .mjs for the literal
 * signature and this test is not one of its sanctioned seats. Assembling
 * it keeps the gate green while the assertion below still checks the exact
 * contiguous signature (and its whitespace-free form) in every kit file. */
const ARCH_SIG = ["A8", "8", "0", "0", "1", "24", "15"].join(" ");
const ARCH_SIG_SQUASHED = ARCH_SIG.replace(/\s+/g, ""); /* whitespace-insensitive */
const RETIRED_ARCH_PATH = ["M8 27L8 15", ARCH_SIG, "L24 27Z"].join("");

test("no forbidden arc signature anywhere in the kit (any spacing)", () => {
  for (const name of NAMES) {
    const raw = read(RUN_A, name);
    assert.ok(!raw.includes(ARCH_SIG), `${name}: contains the forbidden arc signature verbatim`);
    assert.ok(!raw.replace(/\s+/g, "").includes(ARCH_SIG_SQUASHED), `${name}: contains the forbidden arc signature in some spacing`);
    assert.ok(!raw.includes(RETIRED_ARCH_PATH), `${name}: contains the retired full arch path`);
  }
  /* Stronger: the U family has no arc command at all — only M/L/Q. */
  for (const name of ["mark.svg", "mark-mono.svg", "favicon-16.svg", "favicon-32.svg"]) {
    for (const m of stripComments(read(RUN_A, name)).matchAll(/ d="([^"]+)"/g)) {
      assert.doesNotMatch(m[1], /A\s*[\d.]/, `${name}: the new mark uses no arc command (M/L/Q only)`);
    }
  }
});

/* ── 6. brand.json round-trip ────────────────────────────────────────── */
test("brand.json round-trip: name forms obey the rules, palette pinned", () => {
  const brand = JSON.parse(readFileSync(BRAND_JSON, "utf8"));
  /* the required single-source-of-truth seats, exactly as specified */
  assert.deepEqual(
    {
      name_ar: brand.name_ar,
      name_en: brand.name_en,
      slug: brand.slug,
      domain: brand.domain,
      scheme: brand.scheme,
      bundle_id: brand.bundle_id,
      storage_prefix: brand.storage_prefix,
      npm_scope: brand.npm_scope,
      env_prefix: brand.env_prefix,
      paper: brand.colors.paper,
      ink: brand.colors.ink,
      accent: brand.colors.accent,
    },
    {
      name_ar: "أُلارا",
      name_en: "Ulara",
      slug: "ulara",
      domain: "ulara.ly",
      scheme: "ulara://",
      bundle_id: "ly.ulara.app",
      storage_prefix: "ula-",
      npm_scope: "@ulara",
      env_prefix: "ULARA_",
      paper: "#F5F1E8",
      ink: "#262019",
      accent: "#C43E16",
    },
    "brand.json: the identity primitives drifted from the ULARA takeover specification",
  );

  /* name_ar: the damma is not optional — and the damma-less spelling is
   * forbidden anywhere in the kit. */
  assert.ok([...brand.name_ar].some((c) => c.codePointAt(0) === 0x064f), "name_ar must carry the damma (U+064F)");
  const dammaless = brand.name_ar.replace(/\u064f/g, "");
  assert.notEqual(dammaless, brand.name_ar, "name_ar without the damma must differ from the logo form");
  for (const name of NAMES) {
    assert.ok(!read(RUN_A, name).includes(dammaless), `${name}: the damma-less spelling leaked into the kit`);
  }

  /* name_en: the running-text form in data; all-caps ONLY in the -en
   * lockups' rendered content (comments are prose, not rendered marks). */
  assert.match(brand.name_en, /^[A-Z][a-z]+$/, "name_en must be the running-text form (e.g. 'Ulara')");
  assert.ok(brand.name_en !== brand.name_en.toUpperCase(), "name_en must not be the lockup form");
  for (const name of NAMES) {
    const rendered = stripComments(read(RUN_A, name));
    const isLockupEn = name === "lockup-horizontal-en.svg" || name === "lockup-vertical-en.svg";
    if (isLockupEn) {
      assert.ok(rendered.includes("ULARA"), `${name}: the Latin lockup must render the all-caps wordmark`);
    } else {
      assert.ok(!rendered.includes("ULARA"), `${name}: all-caps ULARA is allowed only inside the -en lockups`);
    }
  }

  /* the Arabic name renders exactly where it should — and nowhere else. */
  const arabicSeats = ["lockup-horizontal-ar.svg", "lockup-vertical-ar.svg", "og-1200x630.svg"];
  for (const name of NAMES) {
    if (arabicSeats.includes(name)) {
      assert.ok(read(RUN_A, name).includes(brand.name_ar), `${name}: must render name_ar`);
    } else {
      assert.ok(!read(RUN_A, name).includes(brand.name_ar), `${name}: must not render Arabic`);
    }
  }
  assert.ok(read(RUN_A, "og-1200x630.svg").includes("نظام تشغيل الجامعة"), "og: the descriptor line is missing");

  /* the palette never moves with the rename — pinned to design-tokens. */
  const tokens = JSON.parse(readFileSync(TOKENS_JSON, "utf8")).color.brand;
  assert.equal(brand.colors.paper, tokens.paper, "colors.paper must equal design-tokens color.brand.paper");
  assert.equal(brand.colors.ink, tokens.ink, "colors.ink must equal design-tokens color.brand.ink");
  assert.equal(brand.colors.accent, tokens.orange, "colors.accent must equal design-tokens color.brand.orange");
});

/* ── 7. committed kit + non-empty files ──────────────────────────────── */
test("the committed kit byte-matches a fresh run and every file is non-empty", () => {
  const committed = readdirSync(COMMITTED).sort();
  assert.deepEqual(committed, NAMES, `shared/brand/ulara must hold exactly the kit (found: ${committed.join(", ")})`);
  for (const name of NAMES) {
    const bytes = readFileSync(join(COMMITTED, name));
    assert.ok(bytes.length > 0, `${name}: committed file is empty`);
    assert.ok(bytes.length > 100, `${name}: committed file is suspiciously small (${bytes.length} bytes)`);
    assert.equal(
      Buffer.compare(bytes, readFileSync(join(RUN_A, name))),
      0,
      `${name}: committed copy drifted from regeneration — run: node scripts/brand/ulara-kit.mjs`,
    );
    assertWellFormed(name, bytes.toString("utf8"));
  }
});
